function paceMedian(paces) {
  const result = [];
  for (let i = 0; i < paces.length; i++) {
    const sorted = paces.slice(0, i + 1).sort((a, b) => a - b);
    const mid = sorted.length >> 1;
    result.push(sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2);
  }
  return result;
}

function paceMedian(paces) {
  const push = (heap, value) => {
    heap.push(value);
    for (let i = heap.length - 1; i > 0;) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = (heap) => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      for (let i = 0; ;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]];
        i = m;
      }
    }
    return top;
  };
  const lower = [], upper = [], result = [];
  for (const pace of paces) {
    if (lower.length && pace > -lower[0]) push(upper, pace);
    else push(lower, -pace);
    if (lower.length > upper.length + 1) push(upper, -pop(lower));
    else if (upper.length > lower.length) push(lower, -pop(upper));
    result.push(lower.length > upper.length ? -lower[0] : (-lower[0] + upper[0]) / 2);
  }
  return result;
}
